// lumenbox metric aggregation
pub fn aggregate_window(buckets: &mut Vec<Bucket>, window_ms: u64) -> f64 {
    let cutoff = now_ms().saturating_sub(window_ms);
    buckets.retain(|b| b.started_ms >= cutoff);
    buckets.iter().map(|b| b.value).sum()
}
